import{activeFrame}from './active-models.js?v=20261023-physicscomplete01';
export function transportFigure({left=4,right=12,leftName='Left',rightName='Right',direction='right',substance='Particles',energy=false,step=0,assessment=false,water=false,supported}={}){const ink=assessment?'#182e44':'#f8f6f2',soft=assessment?'#526f86':'#b7c8d6',dots=(n,side)=>Array.from({length:Math.min(24,Number(n)||0)},(_,i)=>`<${water?'rect':'circle'} ${water?`x="${(side?294:55)+(i%4)*30}" y="${77+Math.floor(i/4)*34}" width="12" height="12" rx="2"`:`cx="${(side?300:61)+(i%4)*30}" cy="${83+Math.floor(i/4)*34}" r="7"`} fill="#ed8b78" stroke="${ink}" stroke-width="1"/>`).join('');return `<svg class="shell-diagram" viewBox="0 0 480 330" role="img" aria-label="${leftName}: ${left}; ${rightName}: ${right}. ${water?'Solute concentration indicators; water is transported.':substance+'.'} ${assessment?'':(direction==='right'?'Left to right':'Right to left')+' requested.'} Equal comparison volumes."><rect x="25" y="48" width="430" height="205" rx="20" fill="${soft}" fill-opacity=".08" stroke="${soft}"/><path d="M232 48V253M248 48V253" stroke="${soft}" stroke-width="3"/>${dots(left,false)}${dots(right,true)}<rect x="222" y="115" width="36" height="65" rx="14" fill="${energy?'#ed8b78':soft}" stroke="${ink}" stroke-width="2"/><text x="130" y="25" fill="${ink}" text-anchor="middle" font-size="13">${leftName}: ${left}</text><text x="353" y="25" fill="${ink}" text-anchor="middle" font-size="13">${rightName}: ${right}</text>${!assessment&&supported!==undefined?`<text x="240" y="240" text-anchor="middle" fill="${ink}" font-size="14">${supported?'✓ Route supported':'× Route blocked'}</text>`:''}${assessment?'':`<path d="${direction==='right'?'M140 278H340M330 271L340 278L330 285':'M340 278H140M150 271L140 278L150 285'}" fill="none" stroke="#ed8b78" stroke-width="3"/>`}<text x="240" y="314" fill="${ink}" text-anchor="middle" font-size="12">${assessment?'Equal comparison volumes':water?'Squares show solute; arrows show net WATER':substance+' · '+(energy?'respiration energy available':'respiration energy unavailable')}</text></svg>`;}
export const activeFigure=(id,energy,step)=>transportFigure({...activeFrame(id,energy,step)});
